SELECT T0."DocEntry", T0."DocNum", T0."DocDate",T0."CreateDate",  T0."CardCode", T0."CardName",  T0."BPLName",T0."DocTotal", T0."Comments",T1."VisOrder"+1 as "Document LineNum",T1."CodeBars",T1."ItemCode",T1."Dscription",T1."UomCode",T1."Price",T1."U_RetailPrice" FROM OPOR T0  INNER JOIN POR1 T1 ON T0."DocEntry" = T1."DocEntry" Where --T0."U_BelowCost"='N' and  T1."U_BelowCst"='Yes' and T0."CANCELED" ='N' and T0."UpdateDate"=CURRENT_DATE  --and LEFT(LPAD(T0."UpdateTS",6,'0'),4)>=TO_CHAR(ADD_SECONDS(CURRENT_TIMESTAMP,-1800), 'HH24MI')
